// `@types/fs-extra`'s shape: a real declaration FILE whose own exports sit on
// top of `export * from "<ambient module>"`. The star's source resolves to no
// file — another package declares it as an ambient module — so a star merge
// that only consults the resolved-file graph drops it, and this module's whole
// export set collapses to `ownFn`/`shadowed`.
export * from "ambmod";

export function ownFn(): boolean;
export function shadowed(): string;
